func TestE3DatabaseURIRefused(t *testing.T) {
	testenv.Isolate(t)
	for _, args := range [][]string{{"ask", "topic"}, {"digest"}, {"mirror", "--verify"}, {"backlog"}, {"read-next"}, {"dedupe"}, {"triage", "stale"}, {"connections", "--library-wide"}} {
		for _, suffix := range []string{"?mode=rw&_pragma=foreign_keys(OFF)", "#fragment"} {
			cmd := RootCmd()
			var out bytes.Buffer
			cmd.SetOut(&out)
			cmd.SetErr(&out)
			cmd.SetArgs(append(args, "--db-path", filepath.Join(t.TempDir(), "data.db")+suffix, "--json"))
			err := cmd.Execute()
			if err == nil || ExitCode(err) != 2 || !strings.Contains(err.Error(), "without ? or #") {
				t.Fatalf("%v err=%v out=%s", args, err, &out)
			}
		}
	}
	cmd := RootCmd()
	cmd.SetArgs([]string{"sync", "--db", "bad?mode=rw"})
	err := cmd.Execute()
	if err == nil || ExitCode(err) != 2 {
		t.Fatalf("db err=%v", err)
	}
}

